package com.wissfind.marketplace.controller; import com.wissfind.marketplace.entity.*;import com.wissfind.marketplace.repo.*;import com.wissfind.marketplace.service.CurrentUser;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/payouts") public class PayoutController {final PayoutRepository r;final UserRepository u;public PayoutController(PayoutRepository r,UserRepository u){this.r=r;this.u=u;} @GetMapping("/mine") @PreAuthorize("hasRole('SELLER')") public List<Payout> mine(){return r.findAll().stream().filter(x->x.seller.id.equals(CurrentUser.id())).toList();} @PostMapping("/request") @PreAuthorize("hasRole('SELLER')") public Payout request(@RequestBody Payout p){p.id=null;p.seller=u.findById(CurrentUser.id()).orElseThrow();p.status="REQUESTED";p.reference="PO-"+System.currentTimeMillis();return r.save(p);} @GetMapping @PreAuthorize("hasRole('ADMIN')") public List<Payout> all(){return r.findAll();} @PatchMapping("/{id}/approve") @PreAuthorize("hasRole('ADMIN')") public Payout approve(@PathVariable Long id){var p=r.findById(id).orElseThrow();p.status="PAID";return r.save(p);}}
